(() => {
  const p = window.__ac;
  const ring = p.prop('--layer-focus-ring-screen');
  const surfaces = {
    surface: p.prop('--surface'),
    surface2: p.prop('--surface-2'),
    layer: p.prop('--layer-bg'),
  };
  const specs = [
    ['diary', 'diary-day-head diary-nav-current'],
    ['search', 'search-hit selected'],
    ['publications', 'pub-toc-line pub-toc-selected'],
  ];
  const rows = specs.map(([key, cls]) => {
    const el = document.createElement('div');
    el.className = cls;
    el.textContent = 'проба';
    document.body.append(el);
    const shadow = getComputedStyle(el).boxShadow;
    el.remove();
    const color = (shadow.match(/rgba?\([^)]+\)/) || [''])[0];
    return { key: key, shadow: shadow, color: color };
  });
  const ratios = {};
  for (const name of Object.keys(surfaces)) {
    ratios[name] = Number(p.ratio(p.parse(ring), p.parse(surfaces[name])).toFixed(3));
  }
  return { ring: ring, surfaces: surfaces, ratios: ratios, rows: rows };
})()

