    (surface) => surface !== '' && p.ratio(p.parse(ring), p.parse(surface)) >= 3,
  );
  return {
    inset_count: colors.length,
    all_on_ring:
      colors.every((color) => color !== '') &&
      colors.every((color) => p.dist(p.parse(color), p.parse(ring)) === 0),
    ring_ge_3_on_all_surfaces: ge3,
  };
})()

